/*
 * Fuzz harness for the XTOS EEG CSV row parser used by
 * tools/xtos-eeg-pipeline (parse_row in pipeline.c).
 *
 * The production parser is sscanf(" %llu , %lf , %lf %c") plus isfinite and
 * int32 range checks. This harness mirrors that logic exactly so arbitrary
 * inputs can be tested in-process under ASan/UBSan without going through
 * files. A byte-level mutation corpus is generated by gen_corpus.py.
 *
 * Additionally exercises the bandpass filter with hostile cutoff values and
 * the SPSC queue push/pop round trip, since the pipeline drives all three.
 */

#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "xtos/signal.h"
#include "xtos/spsc.h"

#define CHANNELS 2

/* Mirror of pipeline.c parse_row */
static int parse_row(const char *line, uint64_t *timestamp_ns,
                     int32_t samples[CHANNELS])
{
    unsigned long long timestamp;
    double first;
    double second;
    char extra;
    int fields;

    fields = sscanf(line, " %llu , %lf , %lf %c", &timestamp, &first, &second, &extra);
    if (fields != 3 || !isfinite(first) || !isfinite(second) ||
        first < (double)INT32_MIN || first > (double)INT32_MAX ||
        second < (double)INT32_MIN || second > (double)INT32_MAX)
        return -1;
    *timestamp_ns = (uint64_t)timestamp;
    samples[0] = (int32_t)llround(first);
    samples[1] = (int32_t)llround(second);
    return 0;
}

int LLVMFuzzerTestOneInput(const unsigned char *data, size_t size)
{
    char line[4096];
    size_t copy = size < sizeof(line) - 1 ? size : sizeof(line) - 1;
    uint64_t ts;
    int32_t samples[CHANNELS];
    int ret;

    memcpy(line, data, copy);
    line[copy] = '\0';

    ret = parse_row(line, &ts, samples);
    if (ret == 0) {
        /* Accepted rows must round-trip within the int32 contract. */
        if ((uint64_t)(int64_t)samples[0] != (uint64_t)(int64_t)samples[0])
            abort();
    }

    /* Also drive the signal filter and queue with values derived from the
     * input, to explore init/process parameter space. */
    if (size >= 4) {
        double low = (double)(data[0] % 200) - 10.0;   /* -10..189 Hz-ish */
        double high = (double)(data[1] % 200) - 10.0;
        struct xtos_bandpass_filter filter;
        double in = (double)((int8_t)data[2]) / 8.0;
        double out = 0.0;

        if (xtos_bandpass_init(&filter, 250.0, low, high) == 0)
            (void)xtos_bandpass_process(&filter, &in, &out, 1);

        {
            struct xtos_spsc_queue *queue;
            struct xtos_sample_frame frame;
            struct xtos_sample_frame popped;
            int32_t popped_samples[CHANNELS];

            queue = xtos_spsc_create(4, CHANNELS);
            if (queue) {
                memset(&frame, 0, sizeof(frame));
                frame.timestamp_ns = 1000;
                frame.sequence = 0;
                frame.channels = CHANNELS;
                frame.sample_rate_hz = 250;
                frame.samples_nv = samples;
                if (xtos_spsc_push(queue, &frame) == 0) {
                    if (xtos_spsc_pop(queue, &popped, popped_samples, CHANNELS) == 0) {
                        if (popped.sequence != 0)
                            abort();
                    }
                }
                xtos_spsc_destroy(queue);
            }
        }
    }

    return 0;
}

int main(int argc, char **argv)
{
    int i;
    for (i = 1; i < argc; i++) {
        FILE *f = fopen(argv[i], "rb");
        unsigned char buf[1 << 16];
        size_t n;
        if (!f)
            continue;
        n = fread(buf, 1, sizeof(buf), f);
        fclose(f);
        if (n)
            LLVMFuzzerTestOneInput(buf, n);
    }
    fprintf(stderr, "processed %d corpus file(s)\n", argc - 1);
    return 0;
}
